//! Source-bound compiler for the strict four-bit geometric NoRead scalar.
//!
//! Packed signed coefficients are authoritative. Expanded Q24 scores are
//! independently regenerated by the integer codec; they are not additional
//! learned parameters. The fixed Q25 observation basis is checked against the
//! canonical root coordinates cast to F32 used by the actual context/value
//! interfaces. Group IDs remain signed and retain their pinned ordering.
//!
//! This composition binds the saved scalar source and every actual upstream
//! context/event/span/value and reader artifact. It introduces a new native
//! NoRead producer contract without relabeling the legacy reducer's F32 input
//! contract. The offline learner sums F32 feature products; the compiled path
//! rounds each root factor to Q24 before exact i64 accumulation. This is not a
//! universal float-bit parity claim. The surrounding trunk/readout remains a
//! separate boundary.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::io::Write;
use std::path::Path;

use candle_core::Var;
use serde::{Deserialize, Serialize};
use uor_r4_core::native_geometric::learner::embedding::canonical_h4_roots;
use uor_r4_integer::geometric_no_read::{canonical_basis_q25, NativeGeometricNoRead, NoReadConfig};
use uor_r4_integer::geometric_potential::AddressLane;
use uor_r4_integer::h4_tables::H4Code;

use crate::geometric_context::{BoundFile, CompiledContext};
use crate::geometric_event::CompiledEvents;
use crate::geometric_no_read::NoReadWeights;
use crate::geometric_potential_native::{CompiledGeometricPotentials, PotentialSourceBinding};
use crate::geometric_read_native::{CompiledGeometricRead, ReadSourceBinding};
use crate::geometric_span_native::{CompiledSpanActions, SpanSourceBinding};
use crate::geometric_stack::{StackModel, GEOMETRIC_ADDRESS_RECORD, GEOMETRIC_SPAN_RECORD};
use crate::geometric_value_producer::VALUE_WIDTH;
use crate::geometric_value_producer_native::{
    CompiledValueProducer, ValueParameterIdentity, ValueProducerSourcePaths,
};
use crate::{invalid, sha256_bytes, Result};

pub const SCHEMA: &str = "uor-r4.geometric-no-read-native/1";
const POLICY: &str = "signed-q4[-7,7]-reserved-minus8-reject;fixed-quarter-nat;canonical-F32-root-Q25;root-factor-Q24-round-ties-away-div8;direct-q-times2^22;no-free-wide-gain-or-offset/1";
const PRODUCER: &str = "current-token;actual-post-update-retained-signed-roots;typed-context-radius-presence;prior-held-before-current-step-validity;native-Q24-null-zero-payload-common-denominator;no-donor-state-or-label-input/1";
const LAYOUT: &str = "packed-per-head(bias,token[V],retained[M,4],category[M,33],held[M,4],valid[M]);expanded-per-head(bias,token[V],retained[M,128],category[M,64],held[M,128],valid[M]);M=H*L;zero-root>=120/category>=33/1";
const FILES: [&str; 5] = [
    "metadata.json",
    "no-read-coefficients-q4.bin",
    "no-read-expanded-q24-i32le.bin",
    "observation-basis-q25-i32le.bin",
    "tokenizer-identity.bin",
];

/// Paths to actual saved sources and admitted native components. A different
/// directory spelling with identical bytes does not change model identity.
#[derive(Clone, Copy)]
pub struct NoReadSourcePaths<'a> {
    pub no_read_source: &'a Path,
    pub value: ValueProducerSourcePaths<'a>,
    pub context_native: &'a Path,
    pub value_native: &'a Path,
    pub reducer_native: &'a Path,
}

/// Serialization is kept in the offline compiler, not required by the kernel.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NoReadShape {
    pub vocabulary: usize,
    pub heads: usize,
    pub latent_lanes_per_head: usize,
}
impl From<NoReadConfig> for NoReadShape {
    fn from(c: NoReadConfig) -> Self {
        Self {
            vocabulary: c.vocabulary,
            heads: c.heads,
            latent_lanes_per_head: c.latent_lanes_per_head,
        }
    }
}
impl NoReadShape {
    fn kernel(&self) -> NoReadConfig {
        NoReadConfig {
            vocabulary: self.vocabulary,
            heads: self.heads,
            latent_lanes_per_head: self.latent_lanes_per_head,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CompiledNoReadMetadata {
    pub schema: String,
    pub config: NoReadShape,
    pub layer: usize,
    pub parameters: BTreeMap<String, ValueParameterIdentity>,
    pub source_files: BTreeMap<String, BoundFile>,
    /// Hashes of complete canonical metadata from independently admitted
    /// objects. These bind learned state meaning, not only dimensionality.
    pub dependency_metadata: BTreeMap<String, BoundFile>,
    pub tokenizer: BoundFile,
    pub packed: BoundFile,
    pub expanded: BoundFile,
    pub observation_basis: BoundFile,
    pub coefficient_policy: String,
    pub reference_arithmetic: String,
    pub table_layout: String,
    pub producer_policy: String,
    pub free_coefficients: usize,
    pub expanded_entries: usize,
}

fn bound(bytes: &[u8]) -> BoundFile {
    BoundFile {
        bytes: bytes.len(),
        sha256: sha256_bytes(bytes),
    }
}
fn parameter_identities(
    parameters: &BTreeMap<String, Var>,
) -> Result<BTreeMap<String, ValueParameterIdentity>> {
    parameters
        .iter()
        .map(|(name, v)| {
            let values = v.flatten_all()?.to_vec1::<f32>()?;
            if values.iter().any(|x| !x.is_finite()) {
                return Err(invalid("nonfinite NoRead shadow parameter"));
            }
            let bytes = values
                .into_iter()
                .flat_map(f32::to_le_bytes)
                .collect::<Vec<_>>();
            Ok((
                name.clone(),
                ValueParameterIdentity {
                    shape: v.dims().to_vec(),
                    f32_bytes_sha256: sha256_bytes(&bytes),
                },
            ))
        })
        .collect()
}
fn i32_bytes(values: &[i32]) -> Vec<u8> {
    values.iter().flat_map(|x| x.to_le_bytes()).collect()
}
fn checked_basis() -> Result<Vec<u8>> {
    let basis = canonical_basis_q25();
    for (index, (row, expected)) in basis.iter().zip(canonical_h4_roots()).enumerate() {
        for (actual, coordinate) in row.iter().zip(expected.to_array()) {
            let reference = coordinate as f32;
            let scaled = f64::from(reference) * 33_554_432.;
            if scaled != f64::from(*actual)
                || (f64::from(*actual) / 33_554_432.) as f32 != reference
            {
                return Err(invalid(format!(
                    "NoRead Q25 basis differs from canonical F32 root {index}"
                )));
            }
        }
    }
    Ok(i32_bytes(&basis.into_iter().flatten().collect::<Vec<_>>()))
}
fn snapshot(paths: NoReadSourcePaths<'_>) -> Result<BTreeMap<String, BoundFile>> {
    let deps = paths.value.context_dependencies;
    let mut files = BTreeMap::new();
    for (group, directory, names) in [
        (
            "no_read_source",
            paths.no_read_source,
            vec!["metadata.json", "no-read-parameters.safetensors"],
        ),
        (
            "value_source",
            paths.value.value_source,
            vec!["metadata.json", "value-parameters.safetensors"],
        ),
        (
            "value_native",
            paths.value_native,
            vec![
                "metadata.json",
                "value-tables-i32le.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "context_source",
            paths.value.context_source,
            vec![
                "metadata.json",
                "context-parameters.safetensors",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "context_native",
            paths.context_native,
            vec![
                "metadata.json",
                "context-tables-i32le.bin",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "base",
            deps.base,
            vec![
                "config.json",
                "model.safetensors",
                GEOMETRIC_ADDRESS_RECORD,
                GEOMETRIC_SPAN_RECORD,
            ],
        ),
        (
            "event_source",
            deps.event_source,
            vec![
                "metadata.json",
                "event-parameters.safetensors",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "event_native",
            deps.event_native,
            vec![
                "metadata.json",
                "event-tables-i32le.bin",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "span_native",
            deps.span_native,
            vec![
                "metadata.json",
                "token-actions.bin",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "potential_native",
            deps.potential_native,
            vec![
                "metadata.json",
                "potential-i32le.bin",
                "h4-tables.bin",
                "tokenizer-identity.bin",
            ],
        ),
        (
            "reducer_native",
            paths.reducer_native,
            vec![
                "metadata.json",
                "age-i64le.bin",
                "exp-u32le.bin",
                "tokenizer-identity.bin",
            ],
        ),
    ] {
        for name in names {
            files.insert(
                format!("{group}/{name}"),
                bound(&fs::read(directory.join(name))?),
            );
        }
    }
    Ok(files)
}
fn dependency_metadata(
    context: &CompiledContext,
    potential: &CompiledGeometricPotentials,
    reducer: &CompiledGeometricRead,
    values: &CompiledValueProducer,
    events: &CompiledEvents,
    span: &CompiledSpanActions,
) -> Result<BTreeMap<String, BoundFile>> {
    // Typed objects have private payloads and are admitted by source-backed
    // loaders. Serializing full metadata also binds the payload identities.
    let mut result = BTreeMap::new();
    result.insert(
        "context".into(),
        bound(&serde_json::to_vec(context.metadata())?),
    );
    result.insert(
        "potential".into(),
        bound(&serde_json::to_vec(potential.metadata())?),
    );
    result.insert(
        "reducer".into(),
        bound(&serde_json::to_vec(reducer.metadata())?),
    );
    result.insert(
        "values".into(),
        bound(&serde_json::to_vec(values.metadata())?),
    );
    result.insert(
        "events".into(),
        bound(&serde_json::to_vec(events.metadata())?),
    );
    result.insert("span".into(), bound(&serde_json::to_vec(span.metadata())?));
    Ok(result)
}
fn admit_dependencies(
    config: NoReadConfig,
    paths: NoReadSourcePaths<'_>,
    tokenizer: &[u8],
) -> Result<BTreeMap<String, BoundFile>> {
    let deps = paths.value.context_dependencies;
    let context = CompiledContext::load(
        paths.context_native,
        paths.value.context_source,
        deps,
        tokenizer,
    )?;
    let values = CompiledValueProducer::load(paths.value_native, paths.value, tokenizer)?;
    values.validate_native_context(&context)?;
    let events = CompiledEvents::load(deps.event_native, deps.event_source, deps.base, tokenizer)?;
    let span_config = StackModel::saved_geometric_span(deps.base)?
        .ok_or_else(|| invalid("NoRead source requires saved geometric spans"))?;
    let span_source = SpanSourceBinding::from_files(
        &deps.base.join("model.safetensors"),
        &deps.base.join("config.json"),
        tokenizer,
    )?;
    let span = CompiledSpanActions::load(deps.span_native, &span_source, &span_config)?;
    let potential_source = PotentialSourceBinding::from_directory(deps.base, tokenizer)?;
    let potential = CompiledGeometricPotentials::load(deps.potential_native, &potential_source)?;
    let read_source = ReadSourceBinding::from_directory(deps.base, tokenizer, &potential, 2)?;
    let reducer = CompiledGeometricRead::load(paths.reducer_native, &read_source)?;
    if context.config().vocab_size != config.vocabulary
        || context.config().heads != config.heads
        || context.config().lanes_per_head != config.latent_lanes_per_head
        || events.vocab_size() != config.vocabulary
        || span.vocab_size() != config.vocabulary
        || span.lanes() != config.heads * config.latent_lanes_per_head
        || reducer.metadata().heads != config.heads
        || reducer.metadata().value_width != VALUE_WIDTH
        || reducer.metadata().layer != 2
    {
        return Err(invalid(
            "NoRead shape differs from actual saved producers/reader",
        ));
    }
    dependency_metadata(&context, &potential, &reducer, &values, &events, &span)
}

pub struct CompiledNoRead {
    metadata: CompiledNoReadMetadata,
    native: NativeGeometricNoRead,
    packed: Vec<u8>,
    expanded: Vec<i32>,
    basis: Vec<u8>,
    tokenizer: Vec<u8>,
}
impl CompiledNoRead {
    pub fn compile(
        weights: &NoReadWeights,
        paths: NoReadSourcePaths<'_>,
        tokenizer: &[u8],
    ) -> Result<Self> {
        if tokenizer.is_empty() {
            return Err(invalid(
                "NoRead compiler requires explicit tokenizer identity",
            ));
        }
        weights
            .config()
            .validate()
            .map_err(|e| invalid(e.to_string()))?;
        let before = snapshot(paths)?;
        let saved = NoReadWeights::load(paths.no_read_source)?;
        let identities = parameter_identities(weights.parameters())?;
        if weights.config() != saved.config()
            || identities != parameter_identities(saved.parameters())?
            || weights.packed_coefficients()? != saved.packed_coefficients()?
        {
            return Err(invalid(
                "live NoRead parameters differ from actual saved source",
            ));
        }
        let config = *saved.config();
        let dependencies = admit_dependencies(config, paths, tokenizer)?;
        let basis = checked_basis()?;
        let packed = saved.packed_coefficients()?;
        let native =
            NativeGeometricNoRead::new(config, &packed).map_err(|e| invalid(e.to_string()))?;
        let expanded = native.expanded_q24();
        if snapshot(paths)? != before {
            return Err(invalid(
                "NoRead source/dependencies changed during compilation",
            ));
        }
        let metadata = CompiledNoReadMetadata {
            schema: SCHEMA.into(),
            config: config.into(),
            layer: 2,
            parameters: identities,
            source_files: before,
            dependency_metadata: dependencies,
            tokenizer: bound(tokenizer),
            packed: bound(&packed),
            expanded: bound(&i32_bytes(&expanded)),
            observation_basis: bound(&basis),
            coefficient_policy: POLICY.into(),
            reference_arithmetic: "offline-F32-feature-matmul-sum;native-per-root-Q24-rounding-then-exact-i64-add;loaded-difference-measured-not-assumed-zero/1".into(),
            table_layout: LAYOUT.into(),
            producer_policy: PRODUCER.into(),
            free_coefficients: config.coefficient_count(),
            expanded_entries: expanded.len(),
        };
        Ok(Self {
            metadata,
            native,
            packed,
            expanded,
            basis,
            tokenizer: tokenizer.to_vec(),
        })
    }
    pub fn from_source(paths: NoReadSourcePaths<'_>, tokenizer: &[u8]) -> Result<Self> {
        let weights = NoReadWeights::load(paths.no_read_source)?;
        Self::compile(&weights, paths, tokenizer)
    }
    pub fn config(&self) -> NoReadConfig {
        self.metadata.config.kernel()
    }
    pub fn metadata(&self) -> &CompiledNoReadMetadata {
        &self.metadata
    }
    pub fn validate_for(&self, weights: &NoReadWeights) -> Result<()> {
        if *weights.config() != self.config()
            || parameter_identities(weights.parameters())? != self.metadata.parameters
            || weights.packed_coefficients()? != self.packed
        {
            return Err(invalid(
                "compiled NoRead stale for live shadow/coefficient bits",
            ));
        }
        Ok(())
    }
    pub fn validate_dependencies(
        &self,
        context: &CompiledContext,
        potential: &CompiledGeometricPotentials,
        reducer: &CompiledGeometricRead,
        values: &CompiledValueProducer,
        events: &CompiledEvents,
        span: &CompiledSpanActions,
    ) -> Result<()> {
        if dependency_metadata(context, potential, reducer, values, events, span)?
            != self.metadata.dependency_metadata
        {
            return Err(invalid(
                "compiled NoRead belongs to different actual producer/reader artifacts",
            ));
        }
        Ok(())
    }
    pub fn score(
        &self,
        token: usize,
        latent: &[H4Code],
        observed: &[AddressLane],
        old_held: Option<&[H4Code]>,
    ) -> Result<[i64; 2]> {
        self.native
            .score(token, latent, observed, old_held)
            .map_err(|e| invalid(e.to_string()))
    }
    pub fn save(&self, directory: &Path) -> Result<()> {
        let metadata = serde_json::to_vec_pretty(&self.metadata)?;
        let expanded = i32_bytes(&self.expanded);
        fs::create_dir(directory)?;
        for (name, bytes) in [
            (FILES[0], metadata.as_slice()),
            (FILES[1], self.packed.as_slice()),
            (FILES[2], expanded.as_slice()),
            (FILES[3], self.basis.as_slice()),
            (FILES[4], self.tokenizer.as_slice()),
        ] {
            fs::File::create_new(directory.join(name))?.write_all(bytes)?;
        }
        Ok(())
    }
    pub fn load(directory: &Path, paths: NoReadSourcePaths<'_>, tokenizer: &[u8]) -> Result<Self> {
        let mut names = BTreeSet::new();
        for entry in fs::read_dir(directory)? {
            let entry = entry?;
            if !entry.file_type()?.is_file() {
                return Err(invalid("native NoRead artifact has nonregular file"));
            }
            names.insert(
                entry
                    .file_name()
                    .into_string()
                    .map_err(|_| invalid("native NoRead artifact non-UTF8 filename"))?,
            );
        }
        if names != FILES.iter().map(|s| s.to_string()).collect() {
            return Err(invalid("native NoRead artifact file set differs"));
        }
        let expected = Self::from_source(paths, tokenizer)?;
        let expanded = i32_bytes(&expected.expanded);
        for (name, bytes) in [
            (FILES[1], expected.packed.as_slice()),
            (FILES[2], expanded.as_slice()),
            (FILES[3], expected.basis.as_slice()),
            (FILES[4], tokenizer),
        ] {
            if fs::metadata(directory.join(name))?.len() != bytes.len() as u64
                || fs::read(directory.join(name))? != bytes
            {
                return Err(invalid(
                    "native NoRead payload differs from independent source regeneration",
                ));
            }
        }
        let saved: CompiledNoReadMetadata =
            serde_json::from_slice(&fs::read(directory.join(FILES[0]))?)?;
        if saved != expected.metadata {
            return Err(invalid(
                "native NoRead metadata differs from actual source admission",
            ));
        }
        // Admission also checks the integer codec's independent packed/table
        // relation; a self-resealed arbitrary wide table cannot enter scoring.
        NativeGeometricNoRead::from_parts(expected.config(), &expected.packed, &expected.expanded)
            .map_err(|e| invalid(e.to_string()))?;
        Ok(expected)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::geometric_address::GeometricAddressConfig;
    use crate::geometric_context::{ContextSourcePaths, ContextWeights};
    use crate::geometric_event::EventWeights;
    use crate::geometric_span::GeometricSpanConfig;
    use crate::geometric_stack::{ReadIdentityLatch, ReadScore, StackArch, StackConfig};
    use crate::geometric_value_producer::ValueProducerWeights;
    use candle_core::{Device, Tensor};
    use std::path::PathBuf;
    use std::sync::atomic::{AtomicU64, Ordering};

    const TOKENS: &[u8] = b"NoRead fixture token identities 0..3/v1";
    fn code(index: u8) -> Result<H4Code> {
        H4Code::try_from(index).map_err(|e| invalid(e.to_string()))
    }
    fn observed(root: u8, bin: u8, present: bool) -> Result<AddressLane> {
        AddressLane::new(root, bin, present).map_err(|e| invalid(e.to_string()))
    }
    fn set(weights: &NoReadWeights, values: Vec<f32>) -> Result<()> {
        let v = &weights.parameters()["coefficients"];
        v.set(&Tensor::from_vec(values, v.shape(), &Device::Cpu)?)?;
        Ok(())
    }
    struct Fixture {
        root: PathBuf,
        base: PathBuf,
        event_source: PathBuf,
        event_native: PathBuf,
        span_native: PathBuf,
        potential_native: PathBuf,
        value_source: PathBuf,
        value_native: PathBuf,
        context_source: PathBuf,
        context_native: PathBuf,
        reducer_native: PathBuf,
        no_read_source: PathBuf,
    }
    impl Fixture {
        fn dependencies(&self) -> ContextSourcePaths<'_> {
            ContextSourcePaths {
                base: &self.base,
                event_source: &self.event_source,
                event_native: &self.event_native,
                span_native: &self.span_native,
                potential_native: &self.potential_native,
            }
        }
        fn value_paths(&self) -> ValueProducerSourcePaths<'_> {
            ValueProducerSourcePaths {
                value_source: &self.value_source,
                context_source: &self.context_source,
                context_dependencies: self.dependencies(),
            }
        }
        fn paths(&self) -> NoReadSourcePaths<'_> {
            NoReadSourcePaths {
                no_read_source: &self.no_read_source,
                value: self.value_paths(),
                context_native: &self.context_native,
                value_native: &self.value_native,
                reducer_native: &self.reducer_native,
            }
        }
    }
    fn fixture() -> Result<(Fixture, NoReadWeights)> {
        static SERIAL: AtomicU64 = AtomicU64::new(0);
        let clock = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|e| invalid(e.to_string()))?
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "uor-compiled-null-{}-{clock}-{}",
            std::process::id(),
            SERIAL.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&root)?;
        let f = Fixture {
            base: root.join("base"),
            event_source: root.join("event-source"),
            event_native: root.join("event-native"),
            span_native: root.join("span-native"),
            potential_native: root.join("potential-native"),
            value_source: root.join("value-source"),
            value_native: root.join("value-native"),
            context_source: root.join("context-source"),
            context_native: root.join("context-native"),
            reducer_native: root.join("reducer-native"),
            no_read_source: root.join("no-read-source"),
            root,
        };
        let config = StackConfig {
            arch: StackArch::Geometric,
            vocab_size: 4,
            width: 32,
            heads: 2,
            mlp_hidden: 16,
            context: 8,
            pattern: "rra".into(),
            read: ReadScore::Lorentz,
            rotation: true,
            seed: 29,
            memory: None,
            select: None,
            pointer: None,
        };
        let mut model = StackModel::new(config, &Device::Cpu)?;
        model.set_read_identity_latch(ReadIdentityLatch::Held)?;
        let address = GeometricAddressConfig::new(32, 2)?;
        model.set_geometric_address(address.clone())?;
        let span_config = GeometricSpanConfig::new(32)?;
        model.set_geometric_span(span_config.clone())?;
        model.save(&f.base)?;
        let events = EventWeights::new(4, 2, 173)?;
        events.save_source(&f.event_source, &f.base, TOKENS)?;
        CompiledEvents::compile(&events, &f.event_source, &f.base, TOKENS)?
            .save(&f.event_native)?;
        let span_source = SpanSourceBinding::from_files(
            &f.base.join("model.safetensors"),
            &f.base.join("config.json"),
            TOKENS,
        )?;
        CompiledSpanActions::compile(
            model.variables()["embedding.weight"].as_tensor(),
            &span_config,
            &span_source,
        )?
        .save(&f.span_native)?;
        let potential_source = PotentialSourceBinding::from_directory(&f.base, TOKENS)?;
        let potential = CompiledGeometricPotentials::compile(
            &model.geometric_address_potentials()?,
            &address,
            &potential_source,
        )?;
        potential.save(&f.potential_native)?;
        let read_source = ReadSourceBinding::from_directory(&f.base, TOKENS, &potential, 2)?;
        CompiledGeometricRead::compile(
            model.variables()["layers.02.read.age"].as_tensor(),
            &potential,
            &read_source,
        )?
        .save(&f.reducer_native)?;
        let context = ContextWeights::new_finite_choice(4, 32, 2, 27)?;
        context.save_source(&f.context_source, f.dependencies(), TOKENS)?;
        CompiledContext::compile(&context, &f.context_source, f.dependencies(), TOKENS)?
            .save(&f.context_native)?;
        ValueProducerWeights::new(4, 2, 4, 21)?.save_source(&f.value_source)?;
        CompiledValueProducer::compile(f.value_paths(), TOKENS)?.save(&f.value_native)?;
        let weights = NoReadWeights::new(4, 2, 4)?;
        let c = *weights.config();
        let m = c.lanes();
        let mut coefficients = vec![0.; c.coefficient_count()];
        coefficients[0] = 0.25;
        coefficients[1 + 2] = 0.5;
        // Head 0 reads lane 7, across the context's head partition.
        coefficients[1 + c.vocabulary + 7 * 4] = 0.25;
        let category = 1 + c.vocabulary + m * 4;
        coefficients[category + 7 * 33] = 0.75;
        let held = category + m * 33;
        coefficients[held + 7 * 4] = -0.25;
        coefficients[held + m * 4 + 7] = 0.5;
        coefficients[c.coefficients_per_head()] = -0.5;
        set(&weights, coefficients)?;
        weights.save(&f.no_read_source)?;
        Ok((f, weights))
    }

    #[test]
    fn geometric_no_read_native_canonical_basis_and_packed_width() -> Result<()> {
        let bytes = checked_basis()?;
        assert_eq!(bytes.len(), 120 * 4 * 4);
        let basis = canonical_basis_q25();
        assert_eq!(basis[0], [-(1 << 25), 0, 0, 0]);
        assert_eq!(basis[1], [1 << 25, 0, 0, 0]);
        // Exhaustive comparison is to the independently authored training
        // canonical roots, not merely a codec serialization roundtrip.
        for (q, root) in basis.iter().zip(canonical_h4_roots()) {
            for (x, reference) in q.iter().zip(root.to_array()) {
                assert_eq!((*x as f64 / 33_554_432.) as f32, reference as f32);
            }
        }
        let weights = NoReadWeights::new(4, 1, 4)?;
        let mut reserved = weights.packed_coefficients()?;
        reserved[0] = 8;
        assert!(NativeGeometricNoRead::new(*weights.config(), &reserved).is_err());
        Ok(())
    }

    #[test]
    fn geometric_no_read_native_source_roundtrip_typed_scores() -> Result<()> {
        let (f, weights) = fixture()?;
        let compiled = CompiledNoRead::compile(&weights, f.paths(), TOKENS)?;
        let out = f.root.join("native-no-read");
        compiled.save(&out)?;
        assert!(compiled.save(&out).is_err());
        let restored = CompiledNoRead::load(&out, f.paths(), TOKENS)?;
        assert_eq!(compiled.metadata(), restored.metadata());
        compiled.validate_for(&weights)?;
        let mut latent = vec![code(1)?; 8];
        let mut obs = vec![observed(1, 0, false)?; 8];
        assert_eq!(
            restored.score(2, &latent, &obs, None)?,
            [7 << 22, -(1 << 23)]
        );
        latent[7] = code(0)?;
        assert_eq!(
            restored.score(2, &latent, &obs, None)?,
            [5 << 22, -(1 << 23)]
        );
        latent[7] = code(1)?;
        obs[7] = observed(1, 16, true)?;
        assert_eq!(
            restored.score(2, &latent, &obs, None)?,
            [1 << 24, -(1 << 23)]
        );
        // Valid identity is not an absent span; head 0 has held+valid credit.
        assert_eq!(
            restored.score(2, &latent, &obs, Some(&latent))?,
            [5 << 22, -(1 << 23)]
        );
        assert!(restored.score(4, &latent, &obs, None).is_err());
        assert!(restored.score(2, &latent[..7], &obs, None).is_err());
        assert!(CompiledNoRead::from_source(f.paths(), b"different tokens").is_err());
        fs::remove_dir_all(f.root)?;
        Ok(())
    }

    #[test]
    fn geometric_no_read_native_resealed_payloads_and_orphans_rejected() -> Result<()> {
        let (f, weights) = fixture()?;
        let compiled = CompiledNoRead::compile(&weights, f.paths(), TOKENS)?;
        let out = f.root.join("native-no-read");
        compiled.save(&out)?;
        let original_meta = fs::read(out.join(FILES[0]))?;
        for file in [FILES[1], FILES[2], FILES[3]] {
            let original = fs::read(out.join(file))?;
            let mut changed = original.clone();
            changed[0] ^= 1;
            let mut resealed = compiled.metadata().clone();
            match file {
                "no-read-coefficients-q4.bin" => resealed.packed = bound(&changed),
                "no-read-expanded-q24-i32le.bin" => resealed.expanded = bound(&changed),
                _ => resealed.observation_basis = bound(&changed),
            }
            fs::write(out.join(file), changed)?;
            fs::write(out.join(FILES[0]), serde_json::to_vec(&resealed)?)?;
            assert!(CompiledNoRead::load(&out, f.paths(), TOKENS).is_err());
            fs::write(out.join(file), original)?;
            fs::write(out.join(FILES[0]), &original_meta)?;
        }
        fs::write(out.join("unbound.bin"), b"orphan")?;
        assert!(CompiledNoRead::load(&out, f.paths(), TOKENS).is_err());
        fs::remove_dir_all(f.root)?;
        Ok(())
    }

    #[test]
    fn geometric_no_read_native_stale_live_bits_and_state_generator_rejected() -> Result<()> {
        let (f, weights) = fixture()?;
        let compiled = CompiledNoRead::compile(&weights, f.paths(), TOKENS)?;
        let v = &weights.parameters()["coefficients"];
        let mut changed = v.flatten_all()?.to_vec1::<f32>()?;
        changed[0] = f32::from_bits(changed[0].to_bits() ^ 1);
        set(&weights, changed)?;
        // Hard q4 remains unchanged; the declared actual saved shadow source
        // is nonetheless stale and must not be silently rebound.
        assert_eq!(weights.packed_coefficients()?, compiled.packed);
        assert!(compiled.validate_for(&weights).is_err());
        assert!(CompiledNoRead::compile(&weights, f.paths(), TOKENS).is_err());
        let context = ContextWeights::load_source(&f.context_source, f.dependencies(), TOKENS)?;
        let variable = &context.parameters()["token_transition"];
        let mut coefficients = variable.flatten_all()?.to_vec1::<f32>()?;
        coefficients[0] = f32::from_bits(coefficients[0].to_bits() ^ 1);
        variable.set(&Tensor::from_vec(
            coefficients,
            variable.shape(),
            &Device::Cpu,
        )?)?;
        let other_source = f.root.join("other-context-source");
        let other_native = f.root.join("other-context-native");
        context.save_source(&other_source, f.dependencies(), TOKENS)?;
        let other = CompiledContext::compile(&context, &other_source, f.dependencies(), TOKENS)?;
        other.save(&other_native)?;
        let potential_source = PotentialSourceBinding::from_directory(&f.base, TOKENS)?;
        let potential = CompiledGeometricPotentials::load(&f.potential_native, &potential_source)?;
        let read_source = ReadSourceBinding::from_directory(&f.base, TOKENS, &potential, 2)?;
        let reducer = CompiledGeometricRead::load(&f.reducer_native, &read_source)?;
        let values = CompiledValueProducer::load(&f.value_native, f.value_paths(), TOKENS)?;
        let events = CompiledEvents::load(&f.event_native, &f.event_source, &f.base, TOKENS)?;
        let span_source = SpanSourceBinding::from_files(
            &f.base.join("model.safetensors"),
            &f.base.join("config.json"),
            TOKENS,
        )?;
        let span_config = StackModel::saved_geometric_span(&f.base)?
            .ok_or_else(|| invalid("missing fixture spans"))?;
        let span = CompiledSpanActions::load(&f.span_native, &span_source, &span_config)?;
        assert!(compiled
            .validate_dependencies(&other, &potential, &reducer, &values, &events, &span)
            .is_err());
        let paths = NoReadSourcePaths {
            value: ValueProducerSourcePaths {
                context_source: &other_source,
                ..f.value_paths()
            },
            context_native: &other_native,
            ..f.paths()
        };
        assert!(CompiledNoRead::from_source(paths, TOKENS).is_err());
        fs::remove_dir_all(f.root)?;
        Ok(())
    }
}
